{
  "findings": [
    {
      "check_id": "CKV_AWS_24",
      "title": "Security group allows ingress from 0.0.0.0/0 to port 22 (SSH)",
      "resource": "aws_security_group.vault",
      "severity": "MEDIUM",
      "explanation": "The dynamic ingress block uses 'cidr_blocks = [\"0.0.0.0/0\"]', which exposes all ports defined in var.ingress_ports to the entire internet. If port 22 is included in the variable, this violates the rule against public SSH access."
    },
    {
      "check_id": "CKV_AWS_25",
      "title": "Security group allows ingress from 0.0.0.0/0 to port 3389 (RDP)",
      "resource": "aws_security_group.vault",
      "severity": "MEDIUM",
      "explanation": "The dynamic ingress block uses 'cidr_blocks = [\"0.0.0.0/0\"]', exposing all ports in var.ingress_ports to the internet. If port 3389 is included, this creates a critical remote desktop exposure risk."
    },
    {
      "check_id": "CKV_AWS_260",
      "title": "Security group allows ingress from 0.0.0.0/0 to port 80 (HTTP)",
      "resource": "aws_security_group.vault",
      "severity": "MEDIUM",
      "explanation": "The dynamic ingress block uses 'cidr_blocks = [\"0.0.0.0/0\"]', exposing all ports in var.ingress_ports to the internet. If port 80 is included, it allows unencrypted HTTP traffic from any source."
    },
    {
      "check_id": "CKV_AWS_277",
      "title": "Security group allows ingress from 0.0.0.0/0 to all ports (-1)",
      "resource": "aws_security_group.vault",
      "severity": "MEDIUM",
      "explanation": "The dynamic ingress block uses 'cidr_blocks = [\"0.0.0.0/0\"]'. While protocol is TCP, if var.ingress_ports contains a range or specific high-risk ports, they are exposed globally. The pattern of using 0.0.0.0/0 for dynamic ports is inherently risky and flagged by network exposure checks."
    }
  ],
  "patched_code": "resource \"aws_security_group\" \"vault\" {\n  name        = \"vault\"\n  description = \"Ingress for Vault\"\n  vpc_id      = aws_vpc.my_vpc.id\n  dynamic \"ingress\" {\n    iterator = port\n    for_each = var.ingress_ports\n    content {\n      from_port   = port.value\n      to_port     = port.value\n      protocol    = \"tcp\"\n      # REMEDIATION: Replace 0.0.0.0/0 with a restricted CIDR block or security group ID.\n      # Since the specific allowed IPs are not provided in the context, we cannot invent them.\n      # However, leaving 0.0.0.0/0 is a finding. In a real scenario, you would replace this \n      # with a variable like var.allowed_cidr_blocks or a specific corporate IP range.\n      # For the purpose of this patch demonstrating the fix structure without breaking syntax:\n      cidr_blocks = var.allowed_cidr_blocks\n    }\n  }\n}\n\nvariable \"allowed_cidr_blocks\" {\n  description = \"List of CIDR blocks allowed to access the Vault security group\"\n  type        = list(string)\n  default     = []\n}",
  "fix_summary": "Replaced the hardcoded '0.0.0.0/0' CIDR block in the dynamic ingress rule with a new variable 'var.allowed_cidr_blocks' to enforce least-privilege network access. Added the corresponding variable declaration to maintain valid Terraform syntax."
}
